  if(!fullGM())throw new Error("Добавлять журналы может только мастер.");
  if(!doc||game.journal.get(doc.id)!==doc||meta(doc)?.kind||!Object.hasOwn(SECTIONS,section))throw new Error("Выберите обычный журнал мира и раздел.");
